/**
 * One declarative table of CLI commands. Each command owns its flags, so
 * parsing rejects a flag that belongs to another command, `--help` works on
 * every command, and `agent-sdk help --json` prints the same table for agents.
 */
/**
 * The index of the first positional argument in `rest`, or -1. Skips the
 * value after each string flag in `flags`, so the old form
 * `deployment --team t my-agent` still finds its slug.
 */
export function positionalIndex(rest, flags) {
    for (let index = 0; index < rest.length; index++) {
        const arg = rest[index] ?? "";
        if (arg === "--") {
            return index + 1 < rest.length ? index + 1 : -1;
        }
        if (arg === "-" || !arg.startsWith("-")) {
            return index;
        }
        if (takesValue(arg, flags)) {
            index++;
        }
    }
    return -1;
}
/** True when `arg` is a string flag written without `=`, so the next argument is its value. */
function takesValue(arg, flags) {
    if (arg.includes("=")) {
        return false;
    }
    if (arg.startsWith("--")) {
        return flags[arg.slice(2)]?.type === "string";
    }
    return (arg.length === 2 &&
        Object.values(flags).some((flag) => flag.short === arg.slice(1) && flag.type === "string"));
}
/** True when `rest` has `--<name>` or `--<name>=<value>` for one of `names`. */
export function hasFlag(rest, ...names) {
    return rest.some((arg) => names.some((name) => arg === `--${name}` || arg.startsWith(`--${name}=`)));
}
/**
 * `rest` with its first positional moved to the front as `<flag> <value>`,
 * or undefined when `rest` has no positional.
 */
export function positionalAsFlag(rest, flags, flag) {
    const index = positionalIndex(rest, flags);
    if (index === -1) {
        return undefined;
    }
    return [flag, rest[index] ?? "", ...rest.slice(0, index), ...rest.slice(index + 1)];
}
export function defineCommand(spec) {
    return spec;
}
